package test
import("context";"crypto/rand";"crypto/rsa";"crypto/tls";"crypto/x509";"crypto/x509/pkix";"encoding/pem";"math/big";"net";"os";"path/filepath";"testing";"time";"custom-router/internal/boot";ncrypto "custom-router/internal/crypto";"custom-router/internal/protocol";"custom-router/internal/validator";mock "custom-router/test/mock_validator")
func TestHappyPath(t *testing.T){k,c:=device(t,-time.Minute,time.Hour);s:=server(t,c.SerialNumber.String());defer s.Close();conn:=dial(t,s,c,k);defer conn.Close();h:=protocol.ClientHandshaker{PrivateKey:k,Serial:"NLS-TEST-0001",Chassis:"C1",BoardIDCertificate:pem.EncodeToMemory(&pem.Block{Type:"CERTIFICATE",Bytes:c.Raw})};if e:=h.Run(context.Background(),conn);e!=nil{t.Fatal(e)};eps,e:=validator.Discover(context.Background(),conn);if e!=nil||len(eps)!=2{t.Fatalf("discovery: %v %+v",e,eps)}}
func TestOrgMismatch(t *testing.T){k,c:=device(t,-time.Minute,time.Hour);s:=serverOrg(t,c.SerialNumber.String(),"WRONG");defer s.Close();root:=filepath.Join(t.TempDir(),"root.pem");os.WriteFile(root,s.RootPEM,0600);conn,e:=ncrypto.DTLSClient{RootCAPath:root,Organization:"NLS-LAB",Certificate:tls.Certificate{Certificate:[][]byte{c.Raw},PrivateKey:k},Timeout:time.Second}.Dial(context.Background(),s.Addr());if e==nil{conn.Close();t.Fatal("expected mismatch")};retry(t)}
func TestInvalidSignature(t *testing.T){k,c:=device(t,-time.Minute,time.Hour);wrong,_:=rsa.GenerateKey(rand.Reader,2048);s:=server(t,c.SerialNumber.String());defer s.Close();conn:=dial(t,s,c,wrong);h:=protocol.ClientHandshaker{PrivateKey:wrong,Serial:"NLS-TEST-0001",Chassis:"C1",BoardIDCertificate:pem.EncodeToMemory(&pem.Block{Type:"CERTIFICATE",Bytes:c.Raw})};if e:=h.Run(context.Background(),conn);e!=nil{t.Fatal(e)};if _,e:=validator.Discover(context.Background(),conn);e==nil{t.Fatal("expected bad signature")};conn.Close();retry(t)}
func TestExpiredUnknownSerial(t *testing.T){k,c:=device(t,-2*time.Hour,-time.Hour);s:=server(t,c.SerialNumber.String());defer s.Close();conn:=dial(t,s,c,k);h:=protocol.ClientHandshaker{PrivateKey:k,Serial:"NLS-UNKNOWN",Chassis:"C1",BoardIDCertificate:pem.EncodeToMemory(&pem.Block{Type:"CERTIFICATE",Bytes:c.Raw})};if e:=h.Run(context.Background(),conn);e!=nil{t.Fatal(e)};if _,e:=validator.Discover(context.Background(),conn);e==nil{t.Fatal("expected unknown/expired rejection")};conn.Close();retry(t)}
func retry(t *testing.T){t.Helper();r:=boot.RetryPolicy{Initial:time.Millisecond,Max:time.Millisecond,Ports:[]int{12346,12347,12348}};if _,e:=r.Next(context.Background());e!=nil||r.Attempt()!=1{t.Fatalf("retry: %v",e)}}
func server(t *testing.T,serial string)*mock.Server{return serverOrg(t,serial,"NLS-LAB")};func serverOrg(t *testing.T,serial,org string)*mock.Server{s,e:=mock.New(mock.Config{Organization:org,AuthorizedSerials:map[string]bool{serial:true}});if e!=nil{t.Fatal(e)};return s}
func dial(t *testing.T,s *mock.Server,c *x509.Certificate,k *rsa.PrivateKey)net.Conn{root:=filepath.Join(t.TempDir(),"root.pem");os.WriteFile(root,s.RootPEM,0600);n,e:=ncrypto.DTLSClient{RootCAPath:root,Organization:"NLS-LAB",Certificate:tls.Certificate{Certificate:[][]byte{c.Raw},PrivateKey:k},Timeout:2*time.Second}.Dial(context.Background(),s.Addr());if e!=nil{t.Fatal(e)};return n}
func device(t *testing.T,nb,delta time.Duration)(*rsa.PrivateKey,*x509.Certificate){k,e:=rsa.GenerateKey(rand.Reader,2048);if e!=nil{t.Fatal(e)};now:=time.Now();tt:=&x509.Certificate{SerialNumber:big.NewInt(now.UnixNano()),Subject:pkix.Name{CommonName:"device",Organization:[]string{"NLS-LAB"}},NotBefore:now.Add(nb),NotAfter:now.Add(delta),KeyUsage:x509.KeyUsageDigitalSignature};der,e:=x509.CreateCertificate(rand.Reader,tt,tt,&k.PublicKey,k);if e!=nil{t.Fatal(e)};c,e:=x509.ParseCertificate(der);if e!=nil{t.Fatal(e)};return k,c}
